Field: private final WorkspaceContextRetriever workspaceContextProvider;
Field: private final OllamAssistSettings settings;
Field: private final ExecutorService executor = Executors.newFixedThreadPool(3);
Field: private final DuckDuckGoContentRetriever duckDuckGoContentRetriever;
