Method: fr.baretto.ollamassist.chat.rag.DocumentIndexingPipeline#processBatch
Signature: private void processBatch()
Body: {
    if (!isRunning || processingQueue.isEmpty())
        return;
    processingPhaser.arriveAndAwaitAdvance();
    processingLock.lock();
    try {
        List<String> currentBatch = new ArrayList<>(BATCH_SIZE);
        processingQueue.drainTo(currentBatch, BATCH_SIZE);
        if (!currentBatch.isEmpty()) {
            log.debug("Processing async batch of {} documents", currentBatch.size());
            processDocuments(currentBatch);
            logProgress();
        }
    } catch (Exception e) {
        log.error("Batch processing error", e);
    } finally {
        processingLock.unlock();
    }
}
Method: fr.baretto.ollamassist.chat.rag.DocumentIndexingPipeline#flush
Signature: public synchronized void flush(Producer<Boolean> shouldContinue, IntConsumer consumer)
Body: {
    processingPhaser.register();
    try {
        processingLock.lockInterruptibly();
        try {
            log.info("Starting synchronous flush ({} documents queued)", processingQueue.size());
            List<String> currentBatch = new ArrayList<>();
            while (!processingQueue.isEmpty()) {
                if (Boolean.TRUE.equals(shouldContinue.get())) {
                    break;
                }
                processingQueue.drainTo(currentBatch, SYNCHRONOUS_BATCH_SIZE);
                processDocuments(currentBatch);
                consumer.accept(currentBatch.size());
                currentBatch.clear();
            }
        } finally {
            processingLock.unlock();
        }
    } catch (InterruptedException e) {
        Thread.currentThread().interrupt();
    } finally {
        processingPhaser.arriveAndDeregister();
        log.info("Synchronous flush completed");
    }
}
Method: fr.baretto.ollamassist.chat.rag.DocumentIndexingPipeline#processSingleDocument
Signature: public void processSingleDocument(Document document)
Body: {
    try {
        ingestor.ingest(document);
        totalIndexedDocuments.incrementAndGet();
    } catch (Exception e) {
        handleCorruption();
    }
}
Method: fr.baretto.ollamassist.chat.rag.DocumentIndexingPipeline#start
Signature: private void start()
Body: {
    isRunning = true;
    scheduler.scheduleWithFixedDelay(this::processBatch, 0, 30, TimeUnit.SECONDS);
}

