package fr.baretto.ollamassist.events;

import com.intellij.util.messages.Topic;
import lombok.Builder;
import lombok.Getter;

import java.util.concurrent.CompletableFuture;

public interface FileApprovalNotifier {

    Topic<FileApprovalNotifier> TOPIC = Topic.create("File Approval Request", FileApprovalNotifier.class);

    void requestApproval(ApprovalRequest request);

    /** Outcome of a human-in-the-loop approval request. */
    record ApprovalDecision(boolean approved, @org.jetbrains.annotations.Nullable String rejectionReason) {

        public static ApprovalDecision allow() {
            return new ApprovalDecision(true, null);
        }

        public static ApprovalDecision deny(@org.jetbrains.annotations.Nullable String reason) {
            String trimmed = (reason != null) ? reason.trim() : "";
            return new ApprovalDecision(false, trimmed.isEmpty() ? null : trimmed);
        }

        /**
         * Builds an error message for the LLM tool observation that includes the user's
         * rejection reason when provided, so the model can adapt its next action.
         */
        public String toRejectionMessage(String baseMessage) {
            if (rejectionReason != null && !rejectionReason.isBlank()) {
                return baseMessage + " User rejection reason: \"" + rejectionReason + "\". " +
                        "Adapt your approach based on this feedback.";
            }
            return baseMessage;
        }
    }

    @Getter
    @Builder
    class ApprovalRequest {
        private final String title;
        private final String filePath;
        private final String content;
        private final CompletableFuture<ApprovalDecision> responseFuture;
    }
}
Method: fr.baretto.ollamassist.agent.tools.ToolApprovalHelper#requestApproval
Doc: * Requests user approval and blocks until a decision is made.
     * Returns {@link ApprovalDecision#approved()} immediately when AUTO mode is configured.
     *
     * <p>On rejection the user may optionally provide a reason; this reason is carried in
     * {@link ApprovalDecision#rejectionReason()} so callers can include it in the LLM
     * error observation, enabling the model to adapt rather than repeat the same action.
     *
     * @param title    Dialog title shown in the approval panel
     * @param filePath Path shown as context (file or command)
     * @param content  Preview content (file content, diff, or command string)
     * @return the user's decision (approved flag + optional rejection reason)
     * @throws ApprovalTimeoutException if no response within the configured timeout
Signature: public ApprovalDecision requestApproval(String title, String filePath, String content)
Body: {
    try {
        if (fr.baretto.ollamassist.setting.OllamaSettings.getInstance().isAgentFileApprovalAuto()) {
            log.debug("AUTO approval mode — skipping confirmation for: {}", filePath);
            return ApprovalDecision.allow();
        }
    } catch (Exception e) {
        log.debug("OllamaSettings unavailable — defaulting to MANUAL approval");
    }
    CompletableFuture<ApprovalDecision> future = new CompletableFuture<>();
    FileApprovalNotifier.ApprovalRequest request = FileApprovalNotifier.ApprovalRequest.builder().title(title).filePath(filePath).content(content).responseFuture(future).build();
    project.getMessageBus().syncPublisher(FileApprovalNotifier.TOPIC).requestApproval(request);
    long timeout = timeoutMinutes();
    try {
        return future.get(timeout, TimeUnit.MINUTES);
    } catch (TimeoutException e) {
        future.cancel(true);
        log.warn("Approval request timed out for: {}", filePath);
        throw new ApprovalTimeoutException(filePath);
    } catch (InterruptedException e) {
        Thread.currentThread().interrupt();
        log.warn("Approval request interrupted for: {}", filePath);
        return ApprovalDecision.deny("Interrupted");
    } catch (Exception e) {
        log.error("Approval request failed for: {}", filePath, e);
        return ApprovalDecision.deny(null);
    }
}
