Method: fr.baretto.ollamassist.agent.tools.files.DeleteFileTool#execute
Signature: public ToolResult execute(Map<String, Object> params)
Body: {
    String path = (String) params.get("path");
    if (path == null || path.isBlank()) {
        return ToolResult.failure("Parameter 'path' is required");
    }
    if (path.contains("<<")) {
        return ToolResult.failure("Parameter 'path' contains an unresolved placeholder: '" + path + "'. Use <<var.NAME>> and ensure the step declaring outputVar:\"NAME\" precedes this one.");
    }
    Path absolutePath;
    try {
        absolutePath = FilePathGuard.resolveConfined(path, project);
    } catch (FilePathGuard.PathTraversalException e) {
        log.warn("Path traversal attempt blocked: {}", e.getMessage());
        return ToolResult.failure(e.getMessage());
    } catch (IllegalStateException e) {
        return ToolResult.failure(e.getMessage());
    }
    VirtualFile file = LocalFileSystem.getInstance().refreshAndFindFileByPath(absolutePath.toString());
    if (file == null || !file.exists()) {
        return ToolResult.failure("File not found: " + path);
    }
    var decision = approvalHelper.requestApproval("Delete file?", path, "This action will permanently delete: " + path);
    if (!decision.approved()) {
        return ToolResult.failure(decision.toRejectionMessage("User rejected file deletion: " + path));
    }
    String groupId = (String) params.get("__correlationId");
    AtomicReference<ToolResult> result = new AtomicReference<>();
    try {
        WriteCommandAction.runWriteCommandAction(project, "Agent: delete " + path, groupId, () -> {
            try {
                file.delete(this);
                log.info("File deleted: {}", path);
                result.set(ToolResult.success("File deleted: " + path));
            } catch (IOException e) {
                log.error("Failed to delete file: {}", path, e);
                result.set(ToolResult.failure("Failed to delete file: " + e.getMessage()));
            }
        });
    } catch (Exception e) {
        log.error("WriteCommandAction failed for delete: {}", path, e);
        return ToolResult.failure("Delete action failed: " + e.getMessage());
    }
    return result.get() != null ? result.get() : ToolResult.failure("Write command action produced no result");
}
Method: fr.baretto.ollamassist.chat.ui.ChatThread#handleDetectedToolCall
Signature: private void handleDetectedToolCall(DetectedToolCall detectedCall)
Body: {
    if ("CreateFile".equals(detectedCall.getToolName())) {
        String path = detectedCall.getArguments().get("path");
        String content = detectedCall.getArguments().get("content");
        if (path != null && content != null) {
            log.info("Requesting approval for detected CreateFile call: {}", path);
            // Request user approval with warning indicator
            java.util.concurrent.CompletableFuture<FileApprovalNotifier.ApprovalDecision> approvalFuture = new java.util.concurrent.CompletableFuture<>();
            FileApprovalNotifier.ApprovalRequest request = FileApprovalNotifier.ApprovalRequest.builder().title("⚠️ Tool Call Detected (via text parsing)").filePath(path).content(content).responseFuture(approvalFuture).build();
            contextRef.project().getMessageBus().syncPublisher(FileApprovalNotifier.TOPIC).requestApproval(request);
            // Wait for approval
            ApplicationManager.getApplication().executeOnPooledThread(() -> {
                try {
                    FileApprovalNotifier.ApprovalDecision decision = approvalFuture.get(5, java.util.concurrent.TimeUnit.MINUTES);
                    if (decision.approved()) {
                        log.info("User approved detected tool call");
                        FileCreator fileCreator = new FileCreator(contextRef.project());
                        String result = fileCreator.createFile(path, content);
                        log.info("File creation result: {}", result);
                    } else {
                        log.info("User rejected detected tool call");
                    }
                    // Stop streaming
                    contextRef.project().getMessageBus().syncPublisher(StopStreamingNotifier.TOPIC).stopStreaming();
                } catch (Exception e) {
                    log.error("Error handling detected tool call", e);
                    Thread.currentThread().interrupt();
                }
            });
        }
    }
}

